CalculatedHits.expr:
new CalculatedVar("CalculatedHits").WithMultiplier(delegate(CardModel card, Creature? _)
		{
			if (card.Pile == null)
			{
				return 0m;
			}
			int num = (from e in CombatManager.Instance.History.Entries.OfType<EnergySpentEntry>()
				where e.HappenedThisTurn(card.CombatState) && e.Actor.Player == card.Owner
				select e).Sum((EnergySpentEntry c) => c.Amount);
			if (card.Pile.Type == PileType.Play)
			{
				num -= card.EnergyCost.GetWithModifiers(CostModifiers.All);
			}
			return num;
		})

CalculatedDoom.expr:
new CalculatedVar("CalculatedDoom").WithMultiplier(delegate(CardModel card, Creature? target)
		{
			int num = target?.GetPowerAmount<DoomPower>() ?? 0;
			decimal baseValue = card.DynamicVars["DoomThreshold"].BaseValue;
			return Math.Floor((decimal)num / baseValue);
		})

CalculatedDamage.expr:
new CalculatedDamageVar(ValueProp.Move).WithMultiplier(delegate(CardModel card, Creature? _)
		{
			int num = PileType.Hand.GetPile(card.Owner).Cards.Count;
			CardPile? pile = card.Pile;
			if (pile != null && pile.Type == PileType.Hand)
			{
				num--;
			}
			return -num;
		})

new CalculatedDamageVar(ValueProp.Move).FromOsty().WithMultiplier(delegate(CardModel card, Creature? _)
		{
			Creature osty = card.Owner.Osty;
			return (osty != null && osty.IsAlive) ? osty.MaxHp : 0;
		})

new CalculatedDamageVar(ValueProp.Move).FromOsty().WithMultiplier(delegate(CardModel card, Creature? _)
		{
			Creature osty = card.Owner.Osty;
			return (osty != null && osty.IsAlive) ? osty.CurrentHp : 0;
		})
